-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8664, 31, 'Gesetzliche Mindestausbildungsvergütung anheben (Bund)', 'Hebt die Vergütung genau in den schwach bezahlten Bereichen direkt an; laut BIBB wird aber nur bei 3-4 % der Verträge genau der Mindestsatz vereinbart, und Simulationen warnten vor weniger Ausbildungsplätzen in einzelnen Segmenten.', 'gemischt', 'https://www.bibb.de/de/pressemitteilung_229684.php', 'bund', null, true, 'blind'),
  (8665, 31, 'Schulgeld in schulischen Ausbildungen abschaffen (Bund)', 'Entfällt eine direkte Kostenlast für Auszubildende ohne Vergütung; Länder wie NRW übernehmen Schulgeld bereits mit spürbarer Entlastung. Der Bund kann es nur teils über Berufsgesetze und Finanzierung regeln.', 'belegt', 'https://www.bra.nrw.de/foerderportal-wirtschaft/foerderportal/schultraegerinnen-und-schultraeger/einstieg-die-schulgeldfreiheit-den-gesundheitsfachberufen', 'bund', null, true, 'blind'),
  (8666, 31, 'BAföG-Sätze und Freibeträge regelmäßig an Lebenshaltungskosten anpassen (Bund)', 'Verhindert, dass die Förderung real an Wert verliert; Zuschüsse erhöhen nachweislich den Studienabschluss. Eine Indexierung hält aber nur das bestehende Niveau, ohne es anzuheben.', 'belegt', 'https://www.aeaweb.org/doi/10.1257/app.20180100', 'bund', null, true, 'blind'),
  (8667, 31, 'BAföG unabhängiger vom Elterneinkommen gestalten (Bund)', 'Erweitert den Kreis der Geförderten, deren Eltern faktisch nicht zahlen; Zuschüsse stärken den Abschluss. DIW fand bei BAföG-Reformen aber nur kleine Effekte auf die Studienaufnahme, zudem hohe Mehrkosten.', 'gemischt', 'https://www.diw.de/de/diw_01.c.87747.de/bafoeg-reform_hat_kaum_auswirkungen_auf_die_studienaufnahme.html', 'bund', null, true, 'blind'),
  (8668, 31, 'Konditionen und Ausbau staatlicher Studien- und Bildungskredite (Bund)', 'Feste Zinsen und mehr Kreditvolumen erleichtern die Überbrückung, lösen aber nicht das Einkommensproblem und verlagern die Last als Schulden in die Zukunft; Wirkung auf Erwerbsarbeit kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (8669, 31, 'Aufstiegs-BAföG ausweiten und vereinfachen (Bund)', 'Verbessert die Förderung für Fach- und Fortbildungsschüler über ein bestehendes Gesetz; erreicht aber nur eine kleine Gruppe, für Studierende kaum relevant, Wirkung wenig untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (8670, 31, 'Bundesmittel für Studierendenwerke und soziale Infrastruktur an Hochschulen (Bund)', 'Kann Mensapreise, Beiträge und Wohnkosten senken; der Effekt je Person ist klein und hängt von der Ausgestaltung ab. Hochschulen sind Ländersache, der Bund kann nur über einen Pakt mitfinanzieren.', 'offen', null, 'bund', null, true, 'blind'),
  (8671, 31, 'Förderung von Wohnheimplätzen für Studierende und Auszubildende (Bund)', 'Wohnheimmieten liegen meist deutlich unter Marktmieten, das Bundesprogramm läuft bereits und hat die geförderten Plätze verdoppelt; die Wirkung bleibt aber auf die Bewohner begrenzt und ist kaum evaluiert.', 'offen', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1166126', 'bund', null, true, 'blind'),
  (8672, 31, 'Vergünstigte Mobilität für Auszubildende (Ticket, Führerschein) (Bund)', 'Günstige Tickets entlasten laut DIW vor allem Junge, Auszubildende und Geringverdienende; es bleibt aber eine Entlastung bei einem Kostenposten, und der ÖPNV ist Ländersache mit Bundesmitfinanzierung.', 'belegt', 'https://www.diw.de/de/diw_01.c.869729.de/publikationen/wochenberichte/2023_14_1/9-euro-ticket__niedrigere_preise_allein_staerken_alltagsmobilitaet_mit_oeffentlichen_verkehrsmitteln_nicht.html', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
